:root {
  color-scheme: dark;
  --ink: #f2eee6;
  --muted: #c2c3bb;
  --paper: #111516;
  --surface: #202526;
  --line: #6d7976;
  --forest: #ffad69;
  --forest-dark: #11191a;
  --accent: #ffad69;
  --soft: #303839;
  --focus: #ffbc80;
  --success: #92e2a9;
  --error: #ffacaa;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--ink);
  background: var(--paper);
  line-height: 1.5;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
body { margin: 0; }
