  return res.result?.result?.value;
};
const errors = []; const badResponses = []; const apiTests = [];
listeners.push((msg) => {
  if (msg.method === 'Network.responseReceived' && msg.params.response.status >= 400) badResponses.push(`${msg.params.response.status} ${msg.params.response.url}`);
  if (msg.method === 'Network.requestWillBeSent' && msg.params.request.url.endsWith('/api/test')) apiTests.push(msg.params.request.postData);
  if (msg.method === 'Runtime.exceptionThrown') errors.push(`exception: ${msg.params.exceptionDetails.text}`);
  if (msg.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(msg.params.type)) errors.push(`console.${msg.params.type}: ${JSON.stringify(msg.params.args.map((a) => a.value))}`);
  if (msg.method === 'Log.entryAdded' && ['error', 'warning'].includes(msg.params.entry.level)) errors.push(`log.${msg.params.entry.level}: ${msg.params.entry.text} ${msg.params.entry.url || ''}`);
