  check(invalid.msg === 'Unit ID must be a whole number from 1 to 247. Nothing was sent.' && invalid.ariaInvalid === 'true' && invalid.focus === 'unit_id', 'unit 999 message, aria-invalid and focus', JSON.stringify(invalid));
