  const log = await evaluate(`const t = document.getElementById('log-table'); const region = t.parentElement; const firstTime = t.querySelector('tbody tr td:nth-child(2)'); const time = firstTime.querySelector('time');
    return { selectButtons: [...t.querySelectorAll('button')].filter(b => /select/i.test(b.textContent)).length, buttons: t.querySelectorAll('button').length,
      headers: [...t.querySelectorAll('thead th')].map(h => h.textContent), time: time && time.textContent, title: time && time.title, srTime: firstTime.querySelector('.visually-hidden')?.textContent,
      timeHeight: firstTime.getBoundingClientRect().height, lineHeight: parseFloat(getComputedStyle(firstTime).lineHeight),
      region: { role: region.getAttribute('role'), tabindex: region.getAttribute('tabindex'), label: region.getAttribute('aria-labelledby') && document.getElementById(region.getAttribute('aria-labelledby')).textContent },
      tableWidth: t.scrollWidth, regionWidth: region.clientWidth, flagged: t.querySelectorAll('tr[data-flag]').length };`);
