    const r = await evaluate(`document.getElementById('unit_id').value='1'; for (const f of ['address','quantity','scale']) document.getElementById(f).value = {address:'0',quantity:'1',scale:'1'}[f]; document.getElementById('${field}').value='${value}'; document.getElementById('run-test').click(); await new Promise(r => setTimeout(r, 300)); return { msg: document.getElementById('test-message').textContent, focus: document.activeElement.id, invalid: document.getElementById('${field}').getAttribute('aria-invalid'), unitInvalid: document.getElementById('unit_id').getAttribute('aria-invalid') };`);
