  const ok = await answer(1111, 'MAINT-LAPTOP-07');
  check(ok.status === 'Status: answer verified' && ok.flagged === 1 && ok.hintsHidden, 'typed correct answer verifies, marks the row, hides hints', JSON.stringify(ok));

