  await viewport(360, 780, true);
  await sleep(400);
  const narrow = await evaluate(`await document.querySelector('#log-body button').click(); const r = document.querySelector('.table-scroll'); return { doc: document.documentElement.scrollWidth, body: document.body.scrollWidth, inner: window.innerWidth, regionScroll: r.scrollWidth, regionClient: r.clientWidth, note: getComputedStyle(document.querySelector('.scroll-note')).display };`);
