  const frames = await evaluate(`const b = document.querySelector('#log-body button'); b.click(); const row = document.getElementById(b.getAttribute('aria-controls')); return { expanded: b.getAttribute('aria-expanded'), rowVisible: !row.hidden, colspan: row.firstElementChild.colSpan, hex: row.querySelectorAll('.hex').length, width: row.getBoundingClientRect().width, label: b.textContent };`);
  check(frames.expanded === 'true' && frames.rowVisible && frames.colspan === 9 && frames.hex === 2, 'frames open in a full-width row', JSON.stringify(frames));

  // Wrong answers and progressive hints.
  const r1 = await answer(1, 'HMI-01'); const r2 = await answer(2, 'HMI-01');
  check(r2.hintsHidden && r2.hints.length === 0, 'no hint after 2 wrong answers', JSON.stringify(r2.hints));
  const r3 = await answer(3, 'HMI-01');
  check(!r3.hintsHidden && r3.hints.length === 1 && r3.hints[0] === 'Training hint 1: Look at the Function column: which entry changes data instead of reading it?' && r3.message.includes('Training hint 1'), 'hint 1 after 3 wrong answers', JSON.stringify(r3));
  const r4 = await answer(9999, 'HMI-01');
  check(r4.hints.length === 2 && r4.hints[1] === 'Training hint 2: Compare the value read before and after each entry.', 'hint 2 after 4 wrong answers', JSON.stringify(r4.hints));
  check([r1, r2, r3, r4].every((r) => r.status === 'Status: answer not verified' && r.flagged === 0 && !r.message.includes('1111') && !r.message.includes('MAINT')), 'wrong answers stay not verified and reveal nothing');
  const ok = await answer(1111, 'MAINT-LAPTOP-07');
  check(ok.status === 'Status: answer verified' && ok.flagged === 1 && ok.hintsHidden, 'typed correct answer verifies, marks the row, hides hints', JSON.stringify(ok));

  // 360 px: no page overflow, the table scrolls inside its region.
  await viewport(360, 780, true);
  await sleep(400);
  const narrow = await evaluate(`await document.querySelector('#log-body button').click(); const r = document.querySelector('.table-scroll'); return { doc: document.documentElement.scrollWidth, body: document.body.scrollWidth, inner: window.innerWidth, regionScroll: r.scrollWidth, regionClient: r.clientWidth, note: getComputedStyle(document.querySelector('.scroll-note')).display };`);
  check(narrow.doc <= narrow.inner && narrow.body <= narrow.inner, 'no horizontal page overflow at 360 px (Phantom Writer, frames open)', JSON.stringify(narrow));
  check(narrow.regionScroll > narrow.regionClient && narrow.note !== 'none', 'log table scrolls inside its region at 360 px with a visible note');

  // Dismiss persists across reload; reload at 360 px also has no overflow.
  await evaluate(`document.getElementById('tour').hidden = false; document.getElementById('tour-dismiss').click();`);
  await load();
  const after = await evaluate(`return { hidden: document.getElementById('tour').hidden, stored: localStorage.getItem('ghostwire.tourDismissed'), doc: document.documentElement.scrollWidth, inner: window.innerWidth };`);
  check(after.hidden && after.stored === '1', 'tour dismissal remembered after reload', JSON.stringify(after));
  check(after.doc <= after.inner, 'no horizontal page overflow at 360 px after reload', JSON.stringify(after));
  await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: 'reduce' }] });
  const motion = await evaluate(`document.getElementById('tour').hidden = false; const s = getComputedStyle(document.getElementById('tour')); return { reduce: matchMedia('(prefers-reduced-motion: reduce)').matches, transition: s.transitionDuration, animation: s.animationName };`);
  check(motion.reduce && motion.transition === '0s' && motion.animation === 'none', 'tour banner has no motion under reduced motion', JSON.stringify(motion));
} catch (error) {
  check(false, 'script error', error.message);
}
await sleep(300);
check(badResponses.length === 0, 'no HTTP 4xx/5xx responses', badResponses.join('; '));
check(errors.length === 0, 'no console errors, warnings or exceptions', errors.join('; '));
const failed = results.filter((r) => !r.ok).length;
console.log(`\n${results.length - failed}/${results.length} checks passed`);
ws.close(); chrome.kill();
process.exit(failed ? 1 : 0);

